src='''def transform(grid):
    out=[row[:] for row in grid]; h,w=len(grid),len(grid[0])
    # Connect diagonal 1 markers.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    for i,(r1,c1) in enumerate(pts):
        for r2,c2 in pts[i+1:]:
            if abs(r2-r1)==abs(c2-c1):
                dr=1 if r2>r1 else -1;dc=1 if c2>c1 else -1
                r,c=r1+dr,c1+dc
                while (r,c)!=(r2,c2):
                    if grid[r][c] not in (1,6):out[r][c]=1
                    r+=dr;c+=dc
    # 6 markers extend along the opposite diagonal.
    for r,c in [(r,c) for r in range(h) for c in range(w) if grid[r][c]==6]:
        for rr in range(h):
            cc=r+c-rr
            if 0<=cc<w and grid[rr][cc] not in (1,6):out[rr][cc]=6
    return out
'''
